#!/usr/bin/env python3
import sys, os, re, json, fnmatch

EXTS={'asp':'text/asp','css':'text/css','ejs':'text/x-ejs-template','gohtml':'text/x-go-template','handlebars':'text/x-handlebars-template','htm':'text/html','html':'text/html','js':'application/javascript','json':'application/json','mjs':'application/javascript','mustache':'text/x-mustache-template','php':'application/x-httpd-php','rss':'application/rss+xml','svg':'image/svg+xml','tmpl':'text/x-template','webmanifest':'application/manifest+json','xhtml':'application/xhtml+xml','xml':'text/xml'}

def error(s, code=1):
    print('ERROR: '+s,file=sys.stderr); raise SystemExit(code)
def value_args(argv):
    opts={}; inputs=[]; i=0
    flags={'-a':'all','--all':'all','-b':'bundle','--bundle':'bundle','-i':'inplace','--inplace':'inplace','-l':'list','--list':'list','-q':'quiet','--quiet':'quiet','-r':'recursive','--recursive':'recursive','-s':'sync','--sync':'sync','-w':'watch','--watch':'watch','-h':'help','--help':'help','--version':'version','--html-keep-comments':'html_comments','--html-keep-conditional-comments':'html_cond','--html-keep-default-attrvals':'html_defaults','--html-keep-document-tags':'html_doc','--html-keep-end-tags':'html_end','--html-keep-quotes':'html_quotes','--html-keep-special-comments':'html_special','--html-keep-whitespace':'html_ws','--js-keep-var-names':'js_keep','--json-keep-numbers':'json_keep','--svg-keep-comments':'svg_comments','--xml-keep-whitespace':'xml_ws'}
    takes={'-o':'output','--output':'output','--type':'type','--mime':'mime','--url':'url','-v':'verbose','--verbose':'verbose','--css-precision':'css_precision','--css-version':'css_version','--js-precision':'js_precision','--js-version':'js_version','--json-precision':'json_precision','--svg-precision':'svg_precision','--svg-keep-namespaces':'svg_ns','-p':'preserve','--preserve':'preserve','--match':'match','--include':'include','--exclude':'exclude','--ext':'ext'}
    while i<len(argv):
        a=argv[i]
        if a=='--': inputs.extend(argv[i+1:]); break
        if a in flags: opts[flags[a]]=True
        elif a in takes:
            key=takes[a]; opts.setdefault(key,[])
            i+=1
            if i>=len(argv): error('option requires an argument: '+a,2)
            opts[key].append(argv[i])
        elif a.startswith('--') and '=' in a:
            k,v=a.split('=',1)
            if k in takes: opts.setdefault(takes[k],[]).append(v)
            else: error('unknown option '+k,2)
        elif a.startswith('-') and len(a)>2 and a[1] != '-':
            for ch in a[1:]:
                k='-'+ch
                if k in flags: opts[flags[k]]=True
                else: error('unknown option '+k,2)
        elif a.startswith('-'): error('unknown option '+a,2)
        else: inputs.append(a)
        i+=1
    return opts,inputs

def list_types():
    for k,v in EXTS.items(): print(f'{k:<12} {v}')

def minify(text, typ, opts):
    typ=typ.lower().split(';')[0].strip()
    aliases={'css':'text/css','js':'application/javascript','javascript':'application/javascript','json':'application/json','html':'text/html','htm':'text/html','svg':'image/svg+xml','xml':'text/xml','xhtml':'application/xhtml+xml'}
    typ=aliases.get(typ,typ)
    # Functions in format modules are kept deliberately independent of the CLI.
    def optint(name):
        try: return int(opts.get(name,[0])[0])
        except (ValueError,TypeError,IndexError): return 0
    if typ in ('application/json','application/manifest+json'):
        from jsonmin import minify_json
        return minify_json(text, optint('json_precision'), bool(opts.get('json_keep')))
    if typ=='text/css':
        from cssmin import minify_css
        return minify_css(text, optint('css_precision'))
    if typ=='application/javascript':
        from jsmin import minify_js
        out=minify_js(text, opts)
        # These keyword rewrites are safe in expression position; avoid member names.
        out=re.sub(r'(?<![.$\w])true(?![\w$])','!0',out)
        out=re.sub(r'(?<![.$\w])false(?![\w$])','!1',out)
        out=re.sub(r'(?<![.$\w])undefined(?![\w$])','void 0',out)
        return out
    if typ in ('text/html','image/svg+xml','text/xml','application/xhtml+xml'):
        try: from markup import minify_markup
        except ImportError: minify_markup=None
        if minify_markup:
            return minify_markup(text, typ, opts)
    if typ in ('application/json','application/manifest+json'):
        try: return json.dumps(json.loads(text),separators=(',',':'),ensure_ascii=False)
        except Exception: return text
    if typ in ('text/css','application/javascript','text/html','image/svg+xml','text/xml','application/xhtml+xml'):
        # Conservative whitespace compaction fallback; lexical implementations are supplied by modules.
        return re.sub(r'\s+',' ',text).strip()
    error('unknown filetype ')

def main():
    opts,inputs=value_args(sys.argv[1:])
    if opts.get('mime'):
        print("ERROR: deprecated use of '--mime " + opts['mime'][0] + "', please use '--type " + opts['mime'][0] + "' instead",file=sys.stderr)
    if opts.get('help'):
        print('Usage: executable [options] inputs...\n\nOptions:\n  -h, --help                  Help\n  -l, --list                  List all accepted filetypes\n  -o, --output string         Output file or directory\n      --type string           Filetype (eg. css or text/css)\n\nArguments:\n  inputs    Input files or directories, leave blank to use stdin')
        return 0
    if opts.get('version'):
        print('minify 2.24.13'); return 0
    if opts.get('list'): list_types(); return 0
    typ=(opts.get('type') or opts.get('mime') or [''])[0]
    if not inputs:
        if opts.get('sync'): error("--sync doesn't work with stdin and stdout, specify input and output")
        if not typ: error('must specify --type for stdin')
        data=sys.stdin.read()
        sys.stdout.write(minify(data,typ,opts)); return 0
    if opts.get('watch'): error('watch mode is not supported')
    output=(opts.get('output') or [''])[0]
    jobs=[]
    for path in inputs:
        if not os.path.exists(path):
            print(f'ERROR: stat {path}: no such file or directory',file=sys.stderr); continue
        if os.path.isdir(path):
            if not opts.get('recursive'): continue
            for root,dirs,files in os.walk(path):
                dirs[:]=[d for d in dirs if opts.get('all') or not d.startswith('.')]
                for name in files:
                    if not opts.get('all') and name.startswith('.'): continue
                    src=os.path.join(root,name); jobs.append((src,src))
        else: jobs.append((path,path))
    outputs=[]
    for src,dest in jobs:
        ext=os.path.splitext(src)[1].lstrip('.').lower()
        filetype=typ or next((v for k,v in EXTS.items() if k==ext),'')
        custom={}
        for pair in opts.get('ext',[]):
            if '=' in pair: key,val=pair.split('=',1); custom[key.lstrip('.').lower()]=val
            elif ':' in pair: key,val=pair.split(':',1); custom[key.lstrip('.').lower()]=val
        filetype=typ or custom.get(ext,filetype)
        if not filetype:
            error('cannot infer mimetype from extension in '+src+', set --type explicitly')
        try:
            with open(src,encoding='utf-8') as f: data=f.read()
        except Exception as e:
            print(f'ERROR: read {src}: {e}',file=sys.stderr); continue
        try: result=minify(data,filetype,opts)
        except SystemExit: raise
        if opts.get('inplace'): target=src
        elif output:
            target=os.path.join(output,os.path.relpath(src,inputs[0])) if output.endswith(os.sep) or os.path.isdir(output) else output
            os.makedirs(os.path.dirname(target) or '.',exist_ok=True)
        else: outputs.append(result); continue
        with open(target,'w',encoding='utf-8') as f: f.write(result)
    if outputs: sys.stdout.write(('' if opts.get('bundle') else '\n').join(outputs))
    return 0
if __name__=='__main__':
    try: raise SystemExit(main())
    except BrokenPipeError: pass
"""Conservative HTML, XML and SVG minifiers."""
import re

_VOID = set('area base br col embed hr img input link meta param source track wbr'.split())
_BLOCK = set('address article aside blockquote body caption center dd details dialog dir div dl dt fieldset figcaption figure footer form h1 h2 h3 h4 h5 h6 header hgroup hr li main menu nav ol p pre section table tbody td tfoot th thead tr ul'.split())

def _attrs(m, keep_quotes=False, svg=False):
    tag, raw = m.group(1).lower(), m.group(2)
    # Keep attribute spelling/value, remove redundant whitespace and quotes.
    pat = re.compile(r'''([^\s=/>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?''')
    attrs=[]
    for a in pat.finditer(raw):
        name=a.group(1).lower(); val=a.group(2) if a.group(2) is not None else a.group(3) if a.group(3) is not None else a.group(4)
        if svg and name.startswith('xmlns:') and name != 'xmlns:xlink': continue
        if val is None: attrs.append(name); continue
        if tag=='script' and name=='type' and val in ('text/javascript','application/javascript'): continue
        if tag=='style' and name=='type' and val=='text/css': continue
        if name in ('disabled','checked','selected','multiple','readonly','required','autofocus','defer','async','hidden','loop','controls','open','ismap','novalidate','formnovalidate') and val.lower()==name: attrs.append(name); continue
        if not svg:
            if name in ('class','id','title','alt','href','src','name','value') and val=='': continue
            val=re.sub(r'^(?:https?:)?//','//',val) if name in ('href','src','action','poster') else val
            if name=='href' and val.startswith('javascript:'): val='javascript:'+val[11:]
        if not keep_quotes and re.fullmatch(r'[a-zA-Z0-9._:/#?&=+%-]+',val): attrs.append(name+'='+val)
        else:
            q='"' if val.count('"') <= val.count("'") else "'"
            attrs.append(name+'='+q+val+q)
    return '<'+tag+(' '+' '.join(attrs) if attrs else '')

def minify_html(text, opts=None):
    opts=opts or {}; get=lambda key,*aliases: any(opts.get(k,False) for k in (key,)+aliases)
    keep_comments=get('html-keep-comments','keep_comments')
    if not keep_comments: text=re.sub(r'<!--.*?-->','',text,flags=re.S)
    text=re.sub(r'(?is)<!doctype\s+html\s*>','<!doctype html>',text)
    text=re.sub(r'(?is)<!doctype html>','<!doctype html>',text)
    # Normalize tags and attributes without parsing raw-text content.
    text=re.sub(r'<([A-Za-z][\w:-]*)\b([^<>]*?)\s*/?>',lambda m:_attrs(m,get('html-keep-quotes','keep_quotes'))+('>' if m.group(0).endswith('>') else '>'),text)
    text=re.sub(r'</([A-Za-z][\w:-]*)\s*>',lambda m:'</'+m.group(1).lower()+'>',text)
    # Collapse text whitespace while preserving one newline when present.
    text=re.sub(r'>[^<]+<',lambda m:'>'+re.sub(r'\s+','\n' if '\n' in m.group(0) or '\r' in m.group(0) else ' ',m.group(0)[1:-1]).strip()+'<',text)
    if not get('html-keep-document-tags','keep_document_tags'):
        text=re.sub(r'(?i)</?(?:html|head|body)\b[^>]*>','',text)
    if not get('html-keep-end-tags','keep_end_tags'):
        text=re.sub(r'</(?:li|dt|dd|option|tr|td|th|p)\s*>','',text,flags=re.I)
    return text

def minify_xml(text, keep_whitespace=False):
