        if svg and name.startswith('xmlns:') and name != 'xmlns:xlink': continue
        if val is None: attrs.append(name); continue
        if not keep_defaults and tag=='script' and name=='type' and val in ('text/javascript','application/javascript'): continue
        if not keep_defaults and tag=='style' and name=='type' and val=='text/css': continue
