    return text

def minify_svg(text, opts=None):
    opts=opts or {}
    text=minify_xml(text, bool(opts.get('xml-keep-whitespace',False)))
    text=re.sub(r'(?<![\w.])(-?\d+)\.0+(?=[" ,/>])',r'\1',text)
