"""Conservative HTML, XML and SVG minifiers."""
import re

_VOID = set('area base br col embed hr img input link meta param source track wbr'.split())
_BLOCK = set('address article aside blockquote body caption center dd details dialog dir div dl dt fieldset figcaption figure footer form h1 h2 h3 h4 h5 h6 header hgroup hr li main menu nav ol p pre section table tbody td tfoot th thead tr ul'.split())

def _attrs(m, keep_quotes=False, svg=False, keep_defaults=False):
    tag, raw = m.group(1).lower(), m.group(2)
    # Keep attribute spelling/value, remove redundant whitespace and quotes.
    pat = re.compile(r'''([^\s=/>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?''')
    attrs=[]
    for a in pat.finditer(raw):
        name=a.group(1).lower(); val=a.group(2) if a.group(2) is not None else a.group(3) if a.group(3) is not None else a.group(4)
        if svg and name.startswith('xmlns:') and name != 'xmlns:xlink': continue
        if val is None: attrs.append(name); continue
        if not keep_defaults and tag=='script' and name=='type' and val in ('text/javascript','application/javascript'): continue
        if not keep_defaults and tag=='style' and name=='type' and val=='text/css': continue
        if name in ('disabled','checked','selected','multiple','readonly','required','autofocus','defer','async','hidden','loop','controls','open','ismap','novalidate','formnovalidate') and val.lower()==name: attrs.append(name); continue
        if not svg:
            if name in ('class','id','title','alt','href','src','name','value') and val=='': continue
            val=re.sub(r'^(?:https?:)?//','//',val) if name in ('href','src','action','poster') else val
            if name=='href' and val.startswith('javascript:'): val='javascript:'+val[11:]
        if not keep_quotes and re.fullmatch(r'[a-zA-Z0-9._:/#?&=+%-]+',val): attrs.append(name+'='+val)
        else:
            q='"' if val.count('"') <= val.count("'") else "'"
            attrs.append(name+'='+q+val+q)
    return '<'+tag+(' '+' '.join(attrs) if attrs else '')

def minify_html(text, opts=None):
    opts=opts or {}; get=lambda key,*aliases: any(opts.get(k,False) for k in (key,)+aliases)
    keep_comments=get('html-keep-comments','keep_comments','html_comments')
    keep_special=get('html-keep-special-comments','keep_special','html_special','html_cond')
    if not keep_comments:
        if keep_special:
            text=re.sub(r'<!--(?!\s*(?:\[if|#)).*?-->','',text,flags=re.S)
        else: text=re.sub(r'<!--.*?-->','',text,flags=re.S)
    text=re.sub(r'(?is)<!doctype\s+html\s*>','<!doctype html>',text)
    text=re.sub(r'(?is)<!doctype html>','<!doctype html>',text)
    # Normalize tags and attributes without parsing raw-text content.
    text=re.sub(r'<([A-Za-z][\w:-]*)\b([^<>]*?)\s*/?>',lambda m:_attrs(m,get('html-keep-quotes','keep_quotes','html_quotes'),keep_defaults=get('html-keep-default-attrvals','keep_defaults','html_defaults'))+('>' if m.group(0).endswith('>') else '>'),text)
    text=re.sub(r'</([A-Za-z][\w:-]*)\s*>',lambda m:'</'+m.group(1).lower()+'>',text)
    # Collapse text nodes, preserving significant edge spaces between inline tags.
    pieces=re.split(r'(<[^>]*>)',text)
    def tag_info(tok):
        m=re.match(r'<\s*(/?)\s*([A-Za-z][\w:-]*)',tok)
        return (bool(m.group(1)),m.group(2).lower()) if m else (False,'')
    for i,piece in enumerate(pieces):
        if not piece or piece.startswith('<'): continue
        if not piece.strip():
            prev=pieces[i-1] if i else ''; nxt=pieces[i+1] if i+1<len(pieces) else ''
            _,pn=tag_info(prev); _,nn=tag_info(nxt)
            if prev.startswith('<') and nxt.startswith('<') and pn not in _BLOCK and nn not in _BLOCK:
                pieces[i]='\n' if '\n' in piece or '\r' in piece else ' '
            else: pieces[i]=''
            continue
        normalized=re.sub(r'\s+','\n' if '\n' in piece or '\r' in piece else ' ',piece)
        left=bool(normalized[:1].isspace()); right=bool(normalized[-1:].isspace())
        normalized=normalized.strip()
        prev=pieces[i-1] if i else ''; nxt=pieces[i+1] if i+1<len(pieces) else ''
        prev_close,prev_name=tag_info(prev); next_close,next_name=tag_info(nxt)
        preserve_left=prev_close and prev_name not in _BLOCK and not (i>=2 and pieces[i-2].endswith((' ','\n')))
        preserve_right=bool(nxt.startswith('<')) and next_name not in _BLOCK
        pieces[i]=(' ' if left and preserve_left else '')+normalized+(' ' if right and preserve_right else '')
    text=''.join(pieces)
    if not get('html-keep-document-tags','keep_document_tags','html_doc','keep_doc'):
        text=re.sub(r'(?i)</?(?:html|head|body)\b[^>]*>','',text)
    if not get('html-keep-end-tags','keep_end_tags','html_end','keep_end'):
        text=re.sub(r'</(?:li|dt|dd|option|tr|td|th|p)\s*>','',text,flags=re.I)
    return text.rstrip()

def minify_xml(text, keep_whitespace=False, preserve_comments=False):
    if not preserve_comments: text=re.sub(r'<!--.*?-->','',text,flags=re.S)
    # Compact text nodes and remove indentation-only nodes.
    text=re.sub(r'>\s+<','><',text) if not keep_whitespace else re.sub(r'>[ \t]+<','><',text)
    def compact_text(m):
        raw=m.group(1)
        if not raw.strip(): return '>'+m.group(2)
        sep='\n' if '\n' in raw or '\r' in raw else ' '
        val=re.sub(r'[ \t\r\n]+',sep,raw).lstrip()
        if not m.group(2).startswith('</'): val=val.rstrip()
        # Space before a child element can separate adjacent text nodes; before an
        # end tag it is insignificant trailing whitespace.
        if m.group(2).startswith('</'): val=val.rstrip()
        return '>'+val+m.group(2)
    text=re.sub(r'>([^<]*)(<[^>]+>)',compact_text,text)
    def decode_numeric(m):
        try:
            value=int(m.group(1)[1:],16) if m.group(1).lower().startswith('x') else int(m.group(1))
            ch=chr(value)
            return {'&':'&amp;','<':'&lt;','>':'&gt;'}.get(ch,ch)
        except (ValueError,OverflowError): return m.group(0)
    text=re.sub(r'>([^<]*)<',lambda m:'>'+re.sub(r'&#(x[0-9a-fA-F]+|[0-9]+);',decode_numeric,m.group(1))+'<',text)
    text=re.sub(r'<([A-Za-z_][\w:.-]*)([^<>]*?)></\1>',r'<\1\2/>',text)
    return text

def minify_svg(text, opts=None):
    opts=opts or {}
    text=minify_xml(text, bool(opts.get('xml-keep-whitespace',False)), bool(opts.get('svg-keep-comments') or opts.get('svg_comments')))
    text=re.sub(r'(?<![\w.])(-?\d+)\.0+(?=[" ,/>])',r'\1',text)
    text=re.sub(r'(?<![\w.])(-?\d+)px(?=[" ,/>])',r'\1',text)
    return text

def minify_markup(text, typ, opts=None):
    opts=opts or {}
    if typ == 'image/svg+xml': return minify_svg(text, opts)
    if typ == 'text/html': return minify_html(text, opts)
    return minify_xml(text, bool(opts.get('xml_ws') or opts.get('xml-keep-whitespace')))
